import Foundation

enum GuideContent {
    enum Block: Hashable {
        case heading(String), text(String), picture(String, String), question(String, String)
    }
    static let blocks: [Block] = [
        .heading("Start here"),
        .text("Welcome to *[demo]. This song is a guide to everything in the app. Scroll through, and delete it from your songs whenever you like."),
        .text("Everything saves as you type, and syncs to every device you’re signed in on."),
        .heading("Writing"),
        .text("Tap + to start a song. Give it a title, then write: every line is a lyric line."),
        .text("Put a section name on its own line in square brackets, like [Verse] or [Bridge]. Write your chorus once under [Chorus]. Next time, type [Chorus] and press Return, and it fills itself in."),
        .picture("guide-write", "Select words to make them bold, colour them, or highlight them. Highlights mark a Hook, a line to Rework, or an Idea."),
        .heading("Rhymes & words"),
        .text("The rhyme bar above the keyboard rhymes with the word you just wrote. Tap one to put it in."),
        .picture("guide-rhymes", "Switch it to Perfect, Near, Phrases, Synonyms, Opposites, Define and more. Pull it up for the full Dictionary."),
        .text("Rhyme map colours the words that rhyme with each other. Syllable counts shows how long each line runs, so your verses sit evenly. Both are at the top of the song."),
        .picture("guide-map", "Rhyme map and Syllable counts, both switched on."),
        .heading("When you’re stuck"),
        .text("Muse deals out quick prompts and exercises when the page is blank."),
        .text("Lines writes rhyming next lines in your voice. Writing voice sets that voice: genre, mood and style. Listen to the whole song makes every suggestion fit what you’ve written so far."),
        .text("Rate gives an honest co-writer’s read: a score, what’s working, and notes you can act on."),
        .picture("guide-rate", "Rate’s notes point at the lines they’re about."),
        .heading("Ideas & voice memos"),
        .text("Ideas sits at the top of your songs. It’s a quick jot for stray lines, titles and concepts: tap + to jot one."),
        .text("Record a voice memo the moment a melody turns up. When an idea grows, start a song from it."),
        .picture("guide-ideas", "Lines, ideas, concepts and memos, all in one place."),
        .heading("Details & release"),
        .text("Open ••• › Details for chords, key, tempo, capo, tuning and a status: Idea, Draft, Demo or Finished."),
        .text("••• › Credits keeps the writers and their splits, plus the release details: ISRC, UPC, release date and label. Once a song is out, Find Release looks it up on Apple Music and fills them in for you."),
        .picture("guide-details", "Details for the music. Credits for who wrote it and where it came out."),
        .heading("Audio & lyric sync"),
        .text("In ••• › Audio, add each version of the song: voice memo, demo, mix, master. Tick the one that’s current. Stems, artwork and session files can live with the song too."),
        .text("Sync Lyrics listens to the current version and times every line for you. Export .lrc saves the timed lyrics for streaming services and distributors."),
        .picture("guide-sync", "Play with Lyrics lights up each line in time. Tap a line to jump there."),
        .heading("Albums"),
        .text("Gather songs into an album, EP or single with New Album, at the bottom of your songs. Its artwork goes on every song in it, and the album page shows how close each song is to finished."),
        .picture("guide-album", "Read Lyrics shows the whole album’s words, one song after another."),
        .heading("Sharing & co-writing"),
        .text("Share sends a song as a link anyone can open, with its audio, or as an image of the lyrics. Share an album and it gets a page of its own, with every song on it."),
        .picture("guide-share", "A share page: the song, its audio and its words, on any phone or computer."),
        .text("Pick a username in Account so co-writers can find you, then invite them from ••• › Co-write. You can write in the same song at the same time, and see each other’s changes as they happen."),
        .heading("Perform"),
        .text("••• › Perform turns the song into a scrolling teleprompter for the stage or the studio. Set the speed and the text size, and it rolls on by itself."),
        .picture("guide-perform", "Big, clear lyrics that scroll at your pace."),
        .heading("Organising"),
        .text("Make folders, and drag songs between them. Swipe a song left to pin it to the top, or to delete it."),
        .picture("guide-swipe", "Swipe left on any song in the list."),
        .text("On iPhone, add the *[demo] widgets to your Home Screen: record a memo in one tap, or jump back into the song you were writing."),
        .heading("Keeping it safe"),
        .text("Save a Version in ••• › Details › Versions before big changes, and restore it any time. *[demo] also keeps one by itself when you come back to a song after a while."),
        .text("Clean up tidies case, spacing and section tags, ready for streaming services. The original is saved in Versions first."),
        .text("Copy Lyrics from •••, or export every song from Account. On Mac, songs are also saved as files in Documents › [demo] Songs."),
        .heading("Common questions"),
        .question("Where are my songs kept?", "In your account, synced to iPhone, Mac and the web app at hellodemo.app/app. Each device keeps a copy too, so you can keep writing without a connection."),
        .question("Who can see my songs?", "Only you, until you invite a co-writer or send a share link. You can stop a share link any time."),
        .question("How do I get my songs out?", "Copy Lyrics from •••, export a song’s timed lyrics as .lrc, or export every song from Account."),
        .question("I changed something and want it back.", "Open ••• › Details › Versions and restore an earlier version. Save one yourself before big changes."),
        .question("Do the AI features read my songs?", "Only when you use them. Lines, Muse and Rate send what you’re working on to OpenAI. Turn AI Features off in Account and nothing is sent."),
        .question("What does Pro add?", "Demos, mixes and stems with 5 GB of space, voice memos synced everywhere, lyric sync, co-writing, share links, Lines and Rate in your voice, and Perform mode."),
        .question("Where do I get help?", "Account › Contact Support, or email help@hellodemo.app.")
    ]
